    vnDefinition: 'Điểm khác biệt chí mạng trong Optional: orElse(expensiveCall()) luôn luôn thực thi hàm tính toán đắt đỏ đó bất kể Optional có rỗng hay không (Eager Evaluation); trong khi orElseGet(() -> expensiveCall()) sử dụng Supplier lười biếng (Lazy Evaluation) chỉ chạy khi Optional thực sự rỗng.',
    analogy: 'Mua sẵn bữa tối dự phòng: orElse là bạn luôn bỏ tiền mua sẵn một hộp cơm sườn để trên bàn dù chưa biết mình có đi ăn tiệc ngoài hay không; orElseGet là bạn chỉ bấm app đặt đồ ăn khi nào mở tủ lạnh thấy hết thức ăn.',
    codeExample: '// DANGEROUS: Always creates order even if cache hits!\nuserCache.findById(id).orElse(createExpensiveUser());\n// SAFE (Lazy):\nuserCache.findById(id).orElseGet(() -> createExpensiveUser());',
