    category: 'database',
    categoryLabel: 'Database & Storage',
    vnMeaning: 'Mô hình Mở rộng và Thu hẹp (Quy tắc vàng thay đổi schema DB không bao giờ downtime)',
    vnDefinition: 'Kỹ thuật di chuyển cấu trúc cơ sở dữ liệu (Database Migration) không gián đoạn dịch vụ: Chia việc thay đổi thành 3 giai đoạn: (1) Expand: Thêm cột/bảng mới mà vẫn giữ cột cũ; (2) Transition: Mã nguồn ứng dụng ghi đồng thời vào cả hai nơi; (3) Contract: Khi toàn bộ dữ liệu cũ đã đồng bộ xong, tiến hành xóa bỏ cột/bảng cũ.',
    analogy: 'Xây cầu mới thay thế cây cầu cũ hẹp: Bước 1 xây cây cầu mới chạy song song (Expand); Bước 2 phân luồng xe chạy dần sang cầu mới; Bước 3 khi xe đã đi quen cầu mới thì mới tiến hành tháo dỡ cây cầu cũ (Contract).',
    codeExample: '// Step 1: Add column "full_name"\n// Step 2: Code writes to both "name" and "full_name"\n// Step 3: Backfill old rows\n// Step 4: Drop old column "name"',
    collocations: ['Zero downtime schema evolution', 'Phased database migration', 'Dual-write transition period'],
