    vnDefinition: 'Cài đặt Map trong java.util trong đó các Khóa (Keys) được lưu trữ dưới dạng WeakReference. Khi một khóa không còn bất kỳ tham chiếu mạnh (strong reference) nào trỏ tới, Garbage Collector sẽ thu hồi khóa đó và entry tương ứng sẽ tự động biến mất khỏi Map.',
    analogy: 'Tủ giữ áo khoác tại nhà hát: Khi vị khách đã ra về hẳn (không còn tham chiếu), người soát vé tự động dọn sạch chiếc áo khoác bỏ quên trong ngăn tủ.',
    codeExample: 'Map<Key, Value> cache = new WeakHashMap<>(); // Keys automatically discarded when reclaimed by GC',
    collocations: ['WeakReference keys', 'Memory-sensitive caching', 'ReferenceQueue cleanup mechanism'],
    interviewTip: 'Crucial caveat: ONLY the KEYS are held weakly in WeakHashMap, NOT the Values! If a Value holds a strong reference back to the Key, the entry will NEVER be garbage collected, creating a memory leak.',
