    vnDefinition: 'Nguyên lý do Bertrand Meyer đặt ra: Mọi phương thức trong một đối tượng chỉ nên thuộc về một trong hai loại: (1) Command (Thực hiện hành động sửa đổi trạng thái, trả về void) hoặc (2) Query (Truy vấn trả về dữ liệu, không gây ra tác dụng phụ).',
